using HomeLibrary;using Microsoft.AspNetCore.DataProtection;using System.Text.Json;
static class PrivacyBoundaryTests {
 public static void Run(string directory,IDataProtectionProvider protection){Directory.CreateDirectory(directory);using var store=new Store(directory,protection);using var accounts=new BorrowerAccounts(directory);using var vault=new BorrowerVault(directory);
  JsonElement Input(object o)=>JsonSerializer.SerializeToElement(o,Library.Json);JsonElement Change(string a,object o)=>Input(store.Apply(new(a,Input(o),store.Read().Revision)));void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}void Reject(Action action,int status){try{action();throw new Exception("Expected privacy rejection");}catch(LibraryError e){Check(e.Status==status,"server enforces private-record boundary");}}
  var a=accounts.Register(new("private.reader","Long sign-in password!","Private reader","private@example.test",""));a=accounts.Approve(new(a.Id),store);
  Change("addBook",new{isbn="9780140328721",title="Matilda",author="Roald Dahl"});Change("saveReading",new{readerId=a.ReaderId,copyId="BK-0001",status="finished",notes="BORROWER SECRET MUST NOT LEAK"});var own=Change("addReader",new{name="Household admin"}).GetProperty("result").GetProperty("id").GetString()!;Change("saveReading",new{readerId=own,copyId="BK-0001",status="finished",notes="Household-managed note"});
  var json=JsonSerializer.Serialize(store.AdminRead(),Library.Json);Check(!json.Contains("BORROWER SECRET")&&json.Contains("Household-managed note")&&!store.AdminRead().State.Readers.Any(r=>r.Id==a.ReaderId),"admin snapshots/exports omit borrower personal profiles and notes");
  store.Backup(store.Read().State,"privacy-boundary");var backup=store.RestoreEncrypted(File.ReadAllBytes(Path.Combine(directory,"backups","privacy-boundary.hlbackup")));Check(backup.Readers.All(r=>r.Id!=a.ReaderId)&&backup.ReadingEntries.All(e=>e.ReaderId!=a.ReaderId),"new automatic library snapshots omit legacy borrower personal records");
  Reject(()=>store.AdminApply(new("addReader",Input(new{name="Hidden orphan",borrowerId=a.BorrowerId}),store.Read().Revision)),403);
  Reject(()=>store.AdminApply(new("saveReading",Input(new{readerId=a.ReaderId,copyId="BK-0001",status="want"}),store.Read().Revision)),403);Reject(()=>store.AdminApply(new("renameReader",Input(new{readerId=a.ReaderId,name="Stolen",borrowerId=""}),store.Read().Revision)),403);
  var result=JsonSerializer.Serialize(store.AdminApply(new("setLibraryName",Input(new{libraryName="Admin mutation"}),store.Read().Revision)),Library.Json);Check(!result.Contains("BORROWER SECRET"),"admin mutation responses do not re-expose private snapshot");
  var preview=store.AdminHistoryPreview(new(AllReaders:true));Check(preview.Reading==1,"admin clear-history preview excludes borrower personal reading");store.AdminApply(new("clearHistory",Input(new HistorySelection(AllReaders:true,Confirmation:"CLEAR HISTORY",PreviewToken:preview.PreviewToken)),store.Read().Revision));Check(store.Read().State.ReadingEntries.Single().ReaderId==a.ReaderId,"admin clear all preserves borrower private reading");
  var restored=store.AdminRead().State;store.AdminApply(new("restore",Input(restored),store.Read().Revision));Check(store.Read().State.ReadingEntries.Single().Notes.Contains("BORROWER SECRET"),"admin restore retains private borrower records without exporting them");
  var other=accounts.Register(new("another.reader","Another long password!","Other reader","",""));Reject(()=>accounts.Approve(new(other.Id,a.ReaderId),store),400);
  var e=new VaultEnvelope(1,a.Id,Convert.ToBase64String(new byte[16]),Convert.ToBase64String(new byte[12]),Convert.ToBase64String(new byte[48]),Convert.ToBase64String(new byte[12]),Convert.ToBase64String(new byte[48]),Convert.ToBase64String(new byte[12]),Convert.ToBase64String(new byte[48]));
  Reject(()=>vault.Save(other.Id,new(0,e)),400);Reject(()=>store.SaveVault(vault,a.Id,a.ReaderId,new(0,e)),409);
  store.SaveVault(vault,a.Id,a.ReaderId,new(0,e,true,store.Read().Revision));Check(store.Read().State.ReadingEntries.All(x=>x.ReaderId!=a.ReaderId)&&vault.Exists(a.Id),"encrypted vault is committed before current legacy plaintext is erased");Reject(()=>vault.Save(a.Id,new(0,e)),409);vault.Save(a.Id,new(1,e));Check(JsonSerializer.Serialize(vault.Read(a.Id),Library.Json).Contains("\"revision\":2"),"vault revision compare-and-swap prevents stale-device overwrites");Check(!JsonSerializer.Serialize(store.AdminRead(),Library.Json).Contains("wrappedKey"),"admin library export contains neither private ciphertext nor keys");
  vault.Delete(a.Id);Check(!vault.Exists(a.Id),"account vault deletion removes current encrypted document");
 }
}
